  const { appendFileSync } = await import("node:fs");
  const preload = `
    import { appendFileSync } from "node:fs";
    import { DatabaseSync, StatementSync } from "node:sqlite";
    import { threadId, workerData } from "node:worker_threads";
    const file = workerData && workerData.nativeRefusalProofTrace;
    if (file) {
      const where = (db) => { try { return db.location() || ":memory:"; } catch { return "?"; } };
      const log = (event, db) => appendFileSync(file, JSON.stringify({ thread: threadId, event, db }) + "\\n");
      const seen = new WeakSet();
      const touch = (db) => { if (!seen.has(db)) { seen.add(db); log("native handle opened (first statement)", where(db)); } };
      // Log when this thread starts running statements on another agent database.
      const owner = new WeakMap();
      let last;
      const mark = (location) => {
        if (location && location !== last && /openclaw-agent\.sqlite$/.test(location)) {
          last = location;
          log("runs statements on", location);
        }
      };
      for (const method of ["run", "all", "get", "iterate"]) {
        const original = StatementSync.prototype[method];
        if (typeof original === "function") {
          StatementSync.prototype[method] = function (...args) {
            mark(owner.get(this));
            return original.apply(this, args);
          };
        }
      }
      const prepare = DatabaseSync.prototype.prepare;
      DatabaseSync.prototype.prepare = function (sql) {
        touch(this);
        const statement = prepare.call(this, sql);
        owner.set(statement, where(this));
        const lease = /^\\s*(insert|delete)\\b[^;]*agent_database_leases/i.exec(sql);
        if (lease) {
          const location = where(this);
          for (const method of ["run", "all", "iterate", "get"]) {
            const execute = statement[method].bind(statement);
            statement[method] = (...args) => {
              const result = execute(...args);
              log(lease[1].toLowerCase() + " agent_database_leases row", location);
              return result;
            };
          }
        }
        return statement;
      };
      const exec = DatabaseSync.prototype.exec;
      DatabaseSync.prototype.exec = function (sql) { touch(this); mark(where(this)); return exec.call(this, sql); };
      const close = DatabaseSync.prototype.close;
      DatabaseSync.prototype.close = function () {
        const location = where(this);
        const result = close.call(this);
        log("native close", location);
        return result;
      };
    }
  `;
  return {
    ...actual,
    createCpuTrackedWorker(
      filename: string | URL,
