type Execution = ReturnType<typeof capture>;

async function settle(label: string, run: () => Promise<unknown>) {
  const timeout = new Promise<never>((_, reject) =>
    setTimeout(() => reject(new Error("timed out after 30 s")), 30_000).unref(),
  );
  try {
    const value = await Promise.race([run(), timeout]);
    note(`${label}: ok`);
    return { ok: true as const, value };
  } catch (error) {
    note(`${label}: failed: ${String((error as Error)?.message ?? error).slice(0, 160)}`);
    return { ok: false as const, error };
  }
}

function note(event: string) {
  try {
    fs.appendFileSync(proof.trace, `${JSON.stringify({ thread: "host", event })}\n`);
  } catch {}
}

function initialize(execution: Execution, agentId: string, sessionId: string) {
  return execution.runExisting(source(), (scope) =>
    scope.execute({
      type: "session.transcript.initialize",
      input: { sessionKey: `agent:${agentId}:${sessionId}`, sessionId },
    }),
  );
}

it("native trace of a refused existing-file open and its Worker's peers", { timeout: 120_000 }, async () => {
  const stateDir = fs.realpathSync(tempDirs.make("native-refusal-proof-"));
  proof.trace = path.join(stateDir, "trace.jsonl");
  const env = { OPENCLAW_STATE_DIR: stateDir };
  const agent = (agentId: string) => ({
    agentId,
    env,
    path: resolveOpenClawAgentSqlitePath({ agentId, env }),
  });
  const main = agent("main");
  const peers = [agent("peera"), agent("peerb")];
  for (const options of [main, ...peers]) {
    openOpenClawAgentDatabase(options);
    await closeOpenClawAgentDatabaseByPathAsync(options.path, options.agentId);
    expect(readDatabasePathIdentitySync(options.path).key).toMatch(/^file:/);
  }
  // Keep main's file but drop its registry row, as for an agent re-added with an existing
  // database file: its next open registers the file after the native handle exists.
  unregisterOpenClawAgentDatabase({ agentId: main.agentId, path: main.path, env });
  note(
    "setup: main, peera and peerb database files exist (file: identities); none is open; main's registry row is removed, its file kept",
  );

  const executions: Execution[] = [];
  try {
    for (const options of peers) {
      const execution = capture(options);
      executions.push(execution);
      await settle(`${options.agentId} first turn`, () =>
        initialize(execution, options.agentId, "before"),
      );
    }

    const refusal = new Error("Caller cancelled while its agent database was opening");
    let current = true;
    let mainOpen = false;
    let refusedAt: string | undefined;
    const observed = probe.admission(workerAdmission, (request, grant, admit) => {
      const facts = isRecord(request.facts) ? request.facts : {};
      note(
        `admission ${request.stage}${typeof facts.kind === "string" ? ` ${facts.kind}` : ""}${typeof facts.databasePath === "string" ? ` ${facts.databasePath === main.path ? "main path" : path.basename(facts.databasePath)}` : ""}${typeof facts.kind !== "string" && typeof facts.databasePath !== "string" ? ` (facts: ${Object.keys(facts).join(", ") || "none"})` : ""}`,
      );
      if (
        request.stage === "open" &&
        isRecord(request.facts) &&
        request.facts.databasePath === main.path
      ) {
        mainOpen = true;
      }
      if (
        mainOpen &&
        current &&
        request.stage === "prepare" &&
        isRecord(request.facts) &&
        request.facts.kind === "agent-registration-start"
      ) {
        current = false;
        refusedAt = "agent-registration-start";
        note("host: main's caller is revoked; refusing its agent-registration-start admission");
      }
      admit(request, grant);
    });
    const revoked = source();
    revoked.assertCurrent = () => {
      if (!current) {
        throw refusal;
      }
    };
    const rejected = capture(main);
    executions.push(rejected);
    const outcome = await settle("main open with the revoked caller", () =>
      rejected.runExisting(revoked, async () => "not admitted"),
    );
    observed.mockRestore();
    expect(refusedAt).toBe("agent-registration-start");
    expect(outcome.ok).toBe(false);
    note(
      `host: main's open rejected with the caller's own refusal: ${!outcome.ok && outcome.error === refusal}`,
    );

    for (const [index, options] of peers.entries()) {
      await settle(`${options.agentId} second turn on its existing actor`, () =>
        initialize(executions[index]!, options.agentId, "after"),
      );
    }
    const later = capture(main);
    executions.push(later);
    await settle("main later turn with a current caller", () =>
      initialize(later, "main", "later"),
    );
    note("end of scenario");
  } finally {
    note("snapshot before releasing the executions");
    const rendered = render(stateDir, main.path, peers);
    const out = process.env.NATIVE_REFUSAL_PROOF_OUT;
    if (out) {
      fs.writeFileSync(out, rendered);
    }
    await Promise.allSettled(executions.map(async (execution) => execution.release()));
    proof.trace = "";
  }
});

function render(
  stateDir: string,
  mainPath: string,
  peers: { agentId: string; path: string }[],
): string {
  const labels = new Map<string, string>([
    [mainPath, "main agent db"],
    ...peers.map((peer) => [peer.path, `${peer.agentId} agent db`] as [string, string]),
  ]);
  const threads = new Map<number, string>();
  const lines: string[] = [];
  for (const raw of fs.readFileSync(proof.trace, "utf8").split("\n")) {
    if (!raw) {
      continue;
    }
    const entry = JSON.parse(raw) as { thread: number | "host"; event: string; db?: string };
    let event = entry.event;
    const started = /^Worker started \(thread (\d+)/.exec(event);
    if (started) {
      threads.set(Number(started[1]), `W${threads.size + 1}`);
    }
    event = event.replace(/thread (\d+)/, (_, id: string) => threads.get(Number(id)) ?? `thread ${id}`);
    const who = entry.thread === "host" ? "host" : (threads.get(entry.thread) ?? `thread ${entry.thread}`);
    const db = entry.db
      ? (labels.get(entry.db) ??
        (entry.db.startsWith(stateDir)
          ? `<state>/${path.relative(stateDir, entry.db)}`
          : path.basename(entry.db)))
      : undefined;
    lines.push(`${who.padEnd(5)} ${event}${db ? ` | ${db}` : ""}`);
  }
  return `${lines.join("\n")}\n`;
}
